(() => {
'use strict';const c=window.HVT,$=s=>document.querySelector(s);let rows=[],sequence=0;
const status=(text,error=false)=>{$('#profileStatus').textContent=text;$('#profileStatus').classList.toggle('error',error)};
function render(){const kind=$('#historyKind').value,state=$('#historyState').value;const list=rows.filter(r=>(kind==='all'||r.kind===kind)&&(state==='all'||String(r.completed)===state));$('#profileCounts').textContent=rows.length+' nội dung · '+rows.filter(r=>r.completed).length+' đã hoàn thành';$('#historyList').innerHTML=list.length?list.map(r=>`<article class="history-card"><div><p class="eyebrow">${r.kind==='video'?'VIDEO':r.kind==='kinh'?'KINH':'SÁCH'} · ${r.completed?'ĐÃ HOÀN THÀNH':r.kind==='video'?'ĐANG XEM':'ĐANG ĐỌC'}</p><h3>${c.esc(r.title)}</h3><p>${r.page_order?'Đọc đến Trang '+r.page_order:r.kind==='video'&&r.video_seconds?'Vị trí video: '+Math.floor(r.video_seconds/60)+' phút '+Math.floor(r.video_seconds%60)+' giây':'Đã mở nội dung'} · ${c.esc(new Date(r.updated_at).toLocaleString('vi-VN'))}</p></div><div class="history-actions"><a class="button primary" href="${c.esc(window.HVTCommunity.resourceLink(r.resource_id,r.section_id,r.video_seconds))}">${r.completed?'Mở lại':'Tiếp tục'} ↗</a><button type="button" class="text-link" data-history-complete="${c.esc(r.resource_id)}">${r.completed?'Chuyển về đang tiếp tục':'Đánh dấu đã xong'}</button></div></article>`).join(''):'<p class="content-empty">Chưa có nội dung phù hợp. Mở Kinh, Sách hoặc Video trong thư viện để bắt đầu lịch sử của bạn.</p>'}
async function load(){const token=++sequence,user=c.currentUser();rows=[];$('#profilePrivate').hidden=!user;$('#profileGuest').hidden=!!user;$('#passwordForm').reset();if(!user){$('#historyList').innerHTML='';status('Đăng nhập để xem hồ sơ riêng. Thư viện vẫn mở cho mọi người.');return}$('#profileName').textContent=user.user_metadata?.display_name||'Bạn đọc Hiểu và Thương';$('#profileEmail').textContent=user.email||'';status('Đang tải lịch sử…');try{let offset=0,all=[];while(true){const page=await c.api('/rest/v1/member_activity?select=*&user_id=eq.'+encodeURIComponent(user.id)+'&order=updated_at.desc,resource_id.asc&limit=1000&offset='+offset);if(token!==sequence||c.currentUser()?.id!==user.id)return;all.push(...page);if(page.length<1000)break;offset+=page.length}rows=all;render();status('Lịch sử chỉ hiển thị cho tài khoản của bạn. Video ngoài dùng nút đánh dấu đã xem xong.')}catch{if(token===sequence)status('Chưa tải được lịch sử. Kiểm tra kết nối và chạy upgrade-profile-posts-ratings.sql nếu chưa cập nhật V8.',true)}}
$('#historyKind').onchange=$('#historyState').onchange=render;$('#profileRefresh').onclick=load;$('#profileLogin').onclick=()=>$('#accountBtn').click();
$('#historyList').onclick=async e=>{const b=e.target.closest('[data-history-complete]');if(!b)return;const row=rows.find(r=>r.resource_id===b.dataset.historyComplete),actor=c.currentUser()?.id;if(!row||!actor)return;b.disabled=true;try{await window.HVTCommunity.record({id:row.resource_id},!row.completed);if(c.currentUser()?.id===actor)await load()}catch{status('Chưa đổi được trạng thái. Nội dung có thể đã được gỡ khỏi thư viện.',true);b.disabled=false}};
$('#passwordForm').onsubmit=async e=>{e.preventDefault();const form=e.target,data=new FormData(form),button=$('#passwordSubmit');if(data.get('new_password')!==data.get('confirm_password')){status('Hai mật khẩu mới chưa trùng nhau.',true);return}button.disabled=true;status('Đang xác minh và đổi mật khẩu…');try{await c.changePassword(data.get('current_password'),data.get('new_password'));form.reset();status('Đã đổi mật khẩu. Lần đăng nhập sau, dùng mật khẩu mới.')}catch(error){form.reset();status('Chưa đổi được mật khẩu: '+error.message,true)}finally{button.disabled=false}};
for(const event of ['hvt-auth-change','hvt-auth-lost'])window.addEventListener(event,load);load();
})();
